const http = require('http');
const { URL } = require('url');
const crypto = require('crypto');

const PORT = 8443;
const MAX_BODY = 1048576;

// Request context pool for performance (reuses objects)
class RequestContext {
  constructor() {
    this.id = '';
    this.tags = {};
    this.sanitized = false;
    this.metadata = {};
  }
  reset() {
    this.id = '';
    this.tags = {};
    this.sanitized = false;
    this.metadata = {};
  }
}

const contextPool = Array.from({length: 50}, () => new RequestContext());
let poolIndex = 0;

function acquireContext() {
  const ctx = contextPool[poolIndex % contextPool.length];
  ctx.reset();
  poolIndex++;
  return ctx;
}

// Thorough sanitization - strips ALL control characters including CR/LF
function sanitizeValue(str) {
  if (typeof str !== 'string') return '';
  // Remove all control characters (0x00-0x1f) and DEL (0x7f)
  return str.replace(/[\x00-\x1f\x7f]/g, '').substring(0, 128);
}

// Middleware pipeline
const middlewares = [];

// Audit logging middleware - enriches context with trace info
middlewares.push(function auditEnrich(ctx, req, _res, next) {
  // Parse trace headers for distributed tracing
  const traceParent = req.headers['traceparent'] || '';
  const traceMatch = traceParent.match(/^([0-9a-f]{2})-([0-9a-f]{32})-([0-9a-f]{16})-([0-9a-f]{2})$/);
  if (traceMatch) {
    ctx.metadata.traceId = traceMatch[2];
    ctx.metadata.spanId = traceMatch[3];
  }
  next();
});

// Analytics middleware - runs async, updates context tags from referer
middlewares.push(function analyticsTag(ctx, req, _res, next) {
  // Deferred analytics tagging for A/B test tracking
  setImmediate(() => {
    const referer = req.headers['referer'] || req.headers['x-source-tag'] || '';
    // This writes back to ctx.tags AFTER sanitization has already occurred
    // in the main request handler. The ctx object is shared by reference.
    if (referer) {
      ctx.tags['source'] = referer;
    }
  });
  next();
});

// Rate limiting middleware
const rateLimits = new Map();
middlewares.push(function rateLimit(ctx, req, res, next) {
  const ip = req.socket.remoteAddress || '127.0.0.1';
  const now = Date.now();
  const entry = rateLimits.get(ip) || { count: 0, resetAt: now + 60000 };
  if (now > entry.resetAt) {
    entry.count = 0;
    entry.resetAt = now + 60000;
  }
  entry.count++;
  rateLimits.set(ip, entry);
  if (entry.count > 100) {
    res.writeHead(429, {'Content-Type': 'text/plain'});
    res.end('Rate limited');
    return;
  }
  next();
});

function runMiddlewares(ctx, req, res, callback) {
  let i = 0;
  function next() {
    if (i >= middlewares.length) return callback();
    const mw = middlewares[i++];
    try { mw(ctx, req, res, next); } catch(e) { callback(e); }
  }
  next();
}

// Build response headers using context tags
function buildResponseHeaders(ctx, baseHeaders) {
  const headers = Object.assign({}, baseHeaders);
  // Include all sanitized tags as response headers for debugging
  for (const [key, value] of Object.entries(ctx.tags)) {
    const headerName = `X-Tag-${sanitizeValue(key)}`;
    headers[headerName] = value; // Uses value from ctx.tags directly
  }
  if (ctx.metadata.traceId) {
    headers['X-Trace-ID'] = ctx.metadata.traceId;
  }
  return headers;
}

const server = http.createServer((req, res) => {
  const ctx = acquireContext();

  runMiddlewares(ctx, req, res, (err) => {
    if (err) {
      res.writeHead(500, {'Content-Type': 'text/plain'});
      res.end('Internal error');
      return;
    }

    const url = new URL(req.url, `http://localhost:${PORT}`);

    if (req.method === 'GET' && url.pathname === '/api/status') {
      // Sanitize all query params and store in ctx.tags
      for (const [key, value] of url.searchParams.entries()) {
        ctx.tags[key] = sanitizeValue(value);
      }
      ctx.sanitized = true;

      // Response is sent after a brief delay for metrics collection
      // By this time, the analytics middleware's setImmediate has fired
      // and may have overwritten ctx.tags['source'] with unsanitized referer
      setImmediate(() => {
        const responseHeaders = buildResponseHeaders(ctx, {
          'Content-Type': 'application/json',
          'X-Request-ID': ctx.id || crypto.randomUUID()
        });

        try {
          res.writeHead(200, responseHeaders);
          res.end(JSON.stringify({
            status: 'healthy',
            timestamp: Date.now(),
            tags: ctx.tags
          }));
        } catch(e) {
          res.writeHead(500, {'Content-Type': 'text/plain'});
          res.end('Header error');
        }
      });
    } else if (req.method === 'POST' && url.pathname === '/api/webhook') {
      let body = '';
      req.on('data', chunk => {
        body += chunk;
        if (body.length > MAX_BODY) { req.destroy(); }
      });
      req.on('end', () => {
        try {
          const data = JSON.parse(body);
          // Sanitize webhook callback tag
          ctx.tags['webhook'] = sanitizeValue(data.tag || '');
          ctx.sanitized = true;

          setImmediate(() => {
            const responseHeaders = buildResponseHeaders(ctx, {
              'Content-Type': 'application/json'
            });
            res.writeHead(202, responseHeaders);
            res.end(JSON.stringify({accepted: true}));
          });
        } catch(e) {
          res.writeHead(400, {'Content-Type': 'text/plain'});
          res.end('Invalid JSON');
        }
      });
    } else {
      res.writeHead(404, {'Content-Type': 'text/plain'});
      res.end('Not found');
    }
  });
});

server.listen(PORT, '127.0.0.1', () => {
  console.log(`Service running on port ${PORT}`);
});
